function point(e){const r=canvas.getBoundingClientRect();aim={u:(e.clientX-r.left)/r.width,v:(e.clientY-r.top)/r.height};}
canvas.addEventListener('pointermove',point);canvas.addEventListener('pointerdown',e=>{if(e.button!==0||paused||busy||resultShown)return;e.preventDefault();point(e);pointer=true;canvas.setPointerCapture(e.pointerId);sound.init();canvas.focus();});window.addEventListener('pointerup',()=>pointer=false);canvas.addEventListener('pointercancel',()=>pointer=false);canvas.addEventListener('contextmenu',e=>e.preventDefault());
window.addEventListener('keydown',e=>{if(['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName)||!world||systems.dialog.open||daily.dialog.open)return;if(['Escape','KeyP'].includes(e.code)){e.preventDefault();if(paused){$('#pause-dialog').close();paused=false;resetInput();}else pause();return;}if(paused||resultShown||busy)return;if(['Space','ArrowUp','ArrowLeft','ArrowRight','Digit1','Digit2','Numpad1','Numpad2','KeyQ','KeyF','KeyE','KeyR','ShiftLeft','ShiftRight'].includes(e.code))e.preventDefault();keys.add(e.code);if(e.repeat)return;if(['Digit1','Numpad1'].includes(e.code))actions.push('switch-0');if(['Digit2','Numpad2'].includes(e.code))actions.push('switch-1');if(['Space','KeyW','ArrowUp'].includes(e.code))actions.push('jump');if(e.code==='KeyC')actions.push('pickup');if(e.code==='KeyX')actions.push('settle');if(e.code==='KeyV')actions.push('capture');if(e.code.startsWith('Shift'))actions.push('dash');const k=skillForCode(e.code);if(k)actions.push(k);});window.addEventListener('keyup',e=>keys.delete(e.code));window.addEventListener('blur',pause);document.addEventListener('visibilitychange',()=>{if(document.hidden)pause();});
$('#close-detail').addEventListener('click',()=>$('#stage-detail').close());$('#enter-stage').addEventListener('click',()=>chooseTeam(false));$('#enter-pet-stage').addEventListener('click',()=>chooseTeam(true));$('#capture-pet').addEventListener('click',()=>{if(!paused)actions.push('capture');canvas.focus();});$('#equip-capture-mirror').addEventListener('click',()=>{systems.artifactSelected='mirror';systems.open('artifact');});$('#companion-hud').addEventListener('click',()=>systems.open('pet'));$('#pause').addEventListener('click',pause);$('#pause-dialog').addEventListener('cancel',e=>{e.preventDefault();$('#resume').click();});$('#resume').addEventListener('click',()=>{$('#pause-dialog').close();paused=false;resetInput();canvas.focus();});$('#restart').addEventListener('click',()=>enter());$('#return-map').addEventListener('click',toMap);$('#result-map').addEventListener('click',toMap);$('#result-primary').addEventListener('click',()=>world.campaign.cleared?toMap():enter());$('#result-dialog').addEventListener('cancel',e=>e.preventDefault());$('#retry-load').addEventListener('click',()=>enter());$('#cancel-load').addEventListener('click',toMap);$('#fullscreen').addEventListener('click',()=>document.fullscreenElement?document.exitFullscreen():document.documentElement.requestFullscreen());map();const firstPanel=new URLSearchParams(location.search).get('panel');if(firstPanel==='summon')location.replace('summon.html');else if(firstPanel==='daily')daily.open();else if(['character','bag','skills','forge','artifact','pet'].includes(firstPanel))systems.open(firstPanel);requestAnimationFrame(tick);



